import{c as a,$ as s,Q as t,j as c,m as o,h as n,ax as d,n as i,o as l,S as p}from"./chunks/framework.BqPkuuVc.js";const y=JSON.parse('{"title":"Message Protocol","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/message-protocol.md","filePath":"architecture/message-protocol.md"}'),h={name:"architecture/message-protocol.md"};function u(g,e,m,A,q,E){const r=s("Mermaid");return t(),c("div",null,[e[1]||(e[1]=o(`<h1 id="message-protocol" tabindex="-1">Message Protocol <a class="header-anchor" href="#message-protocol" aria-label="Permalink to &quot;Message Protocol&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a2e/caps/base/protocol.py — A2EMessage, MessageType, Handshake*, A2EError, A2EEvent</span></span></code></pre></div><h2 id="wire-format" tabindex="-1">Wire Format <a class="header-anchor" href="#wire-format" aria-label="Permalink to &quot;Wire Format&quot;">​</a></h2><p>A2E uses <strong>NDJSON</strong> (newline-delimited JSON) as its wire format. Each line is a self-contained JSON object representing one message. Compact JSON encoding (no extra whitespace) is used for efficiency.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{&quot;a2e&quot;:&quot;1.0&quot;,&quot;id&quot;:&quot;a1b2c3&quot;,&quot;type&quot;:&quot;tool/call/req&quot;,&quot;ts&quot;:1716123456.789,...}\\n</span></span>
<span class="line"><span>{&quot;a2e&quot;:&quot;1.0&quot;,&quot;id&quot;:&quot;d4e5f6&quot;,&quot;type&quot;:&quot;tool/call/resp&quot;,&quot;ts&quot;:1716123457.012,...}\\n</span></span></code></pre></div><h2 id="a2emessage-base" tabindex="-1">A2EMessage Base <a class="header-anchor" href="#a2emessage-base" aria-label="Permalink to &quot;A2EMessage Base&quot;">​</a></h2><p>Every A2E message inherits from <code>A2EMessage</code> (Pydantic BaseModel):</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>type</code></td><td><code>str</code></td><td>Message type identifier (e.g. <code>&quot;tool/call/req&quot;</code>)</td></tr><tr><td><code>id</code></td><td><code>str</code></td><td>UUID hex, auto-generated per message</td></tr><tr><td><code>version</code></td><td><code>str</code></td><td>Protocol version, always <code>&quot;1.0&quot;</code></td></tr><tr><td><code>ts</code></td><td><code>float</code></td><td>Unix epoch timestamp</td></tr></tbody></table><p>Methods: <code>to_dict()</code> (serialize), <code>new_id()</code> (regenerate UUID).</p><h2 id="protocol-versioning" tabindex="-1">Protocol Versioning <a class="header-anchor" href="#protocol-versioning" aria-label="Permalink to &quot;Protocol Versioning&quot;">​</a></h2><p>Protocol version is <code>&quot;1.0&quot;</code>, described as a <strong>strict superset of SCP 1.0</strong> (Skill Call Protocol). Unknown message types degrade gracefully — the base type map covers SCP-compatible handshake/ping/pong/shutdown/error, and any unrecognized type falls back to a generic <code>A2EMessage</code>.</p><h2 id="message-lifecycle" tabindex="-1">Message Lifecycle <a class="header-anchor" href="#message-lifecycle" aria-label="Permalink to &quot;Message Lifecycle&quot;">​</a></h2>`,12)),(t(),n(p,null,{default:d(()=>[l(r,{id:"mermaid-90",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20Agent%0A%20%20%20%20participant%20Client%20as%20A2EClient%0A%20%20%20%20participant%20Server%20as%20A2EServer%0A%20%20%20%20participant%20Plugin%0A%0A%20%20%20%20Agent-%3E%3EClient%3A%20connect()%0A%20%20%20%20Client-%3E%3EServer%3A%20handshake%2Freq%20%7Bagent_id%2C%20agent_caps%2C%20auth_token%7D%0A%20%20%20%20Server-%3E%3EClient%3A%20handshake%2Fresp%20%7Bsession_id%2C%20accepted_caps%2C%20max_parallel%7D%0A%0A%20%20%20%20Agent-%3E%3EClient%3A%20rpc(tool%2Fcall%2Freq)%0A%20%20%20%20Client-%3E%3EServer%3A%20tool%2Fcall%2Freq%20%7Btool_name%2C%20arguments%7D%0A%20%20%20%20Server-%3E%3EPlugin%3A%20handle(ToolCallRequest)%0A%20%20%20%20Plugin--%3E%3EServer%3A%20ToolCallResponse%0A%20%20%20%20Server--%3E%3EClient%3A%20tool%2Fcall%2Fresp%20%7Bresult%7D%0A%20%20%20%20Client--%3E%3EAgent%3A%20ToolResult%0A%0A%20%20%20%20Agent-%3E%3EClient%3A%20rpc(memory%2Fstore%2Freq%2C%20event_callback%3Dfn)%0A%20%20%20%20Client-%3E%3EServer%3A%20memory%2Fstore%2Freq%20%7Bentries%7D%0A%20%20%20%20Server-%3E%3EPlugin%3A%20handle(MemoryStoreRequest)%0A%20%20%20%20Plugin--%3E%3EServer%3A%20invoke%2Fevent%20%7Bkind%3A%20progress%2C%20seq%3A%201%7D%0A%20%20%20%20Server--%3E%3EClient%3A%20memory%2Fstore%2Fresp%20%7Bstored%7D%0A%20%20%20%20Client-%3E%3EAgent%3A%20event_callback(A2EEvent)%0A%0A%20%20%20%20Agent-%3E%3EClient%3A%20disconnect()%0A%20%20%20%20Client-%3E%3EServer%3A%20shutdown%20%7Btimeout%3A%2010%7D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="correlation" tabindex="-1">Correlation <a class="header-anchor" href="#correlation" aria-label="Permalink to &quot;Correlation&quot;">​</a></h2><p>RPC requests are correlated by <code>req_id</code> — the client generates a UUID, the server copies it into the response. The client maintains a dict of <code>req_id -&gt; queue.Queue</code>, so multiple concurrent RPCs can be in flight. Events reference their parent request via <code>req_id</code>.</p><h2 id="event-streaming" tabindex="-1">Event Streaming <a class="header-anchor" href="#event-streaming" aria-label="Permalink to &quot;Event Streaming&quot;">​</a></h2><p><code>A2EEvent</code> (type: <code>invoke/event</code>) provides streaming mid-operation updates:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>kind</code></td><td><code>EventKind</code></td><td><code>progress</code>, <code>artifact</code>, <code>log</code>, or <code>status</code></td></tr><tr><td><code>req_id</code></td><td><code>str</code></td><td>Correlates to the originating request</td></tr><tr><td><code>data</code></td><td><code>dict</code></td><td>Payload (progress %, artifact content, log text, status message)</td></tr><tr><td><code>seq</code></td><td><code>int</code></td><td>Monotonic sequence number within the request</td></tr></tbody></table><p>Events are delivered before the final response, enabling progressive UI updates.</p><h2 id="error-handling" tabindex="-1">Error Handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error Handling&quot;">​</a></h2><p><code>A2EError</code> is returned when a message cannot be processed:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>req_id</code></td><td><code>str</code></td><td>The failed request&#39;s ID</td></tr><tr><td><code>code</code></td><td><code>A2EErrorCode</code></td><td>Machine-readable error code</td></tr><tr><td><code>message</code></td><td><code>str</code></td><td>Human-readable error description</td></tr><tr><td><code>detail</code></td><td><code>dict</code></td><td>Additional structured context</td></tr><tr><td><code>retryable</code></td><td><code>bool</code></td><td>Whether the client should retry</td></tr><tr><td><code>capability_name</code></td><td><code>str</code></td><td>Which capability namespace failed</td></tr></tbody></table><p>See <a href="/protocol-spec/error-codes.html">Error Codes</a> for the full list.</p><h2 id="type-registry" tabindex="-1">Type Registry <a class="header-anchor" href="#type-registry" aria-label="Permalink to &quot;Type Registry&quot;">​</a></h2><p>Both client and server maintain a <code>type_registry</code> mapping type strings to Pydantic model classes. The base map (<code>A2E_BASE_TYPE_MAP</code>) covers core types:</p><table tabindex="0"><thead><tr><th>Type String</th><th>Model Class</th></tr></thead><tbody><tr><td><code>handshake/req</code></td><td><code>HandshakeRequest</code></td></tr><tr><td><code>handshake/resp</code></td><td><code>HandshakeResponse</code></td></tr><tr><td><code>invoke/event</code></td><td><code>A2EEvent</code></td></tr><tr><td><code>ping</code></td><td><code>Ping</code></td></tr><tr><td><code>pong</code></td><td><code>Pong</code></td></tr><tr><td><code>shutdown</code></td><td><code>Shutdown</code></td></tr><tr><td><code>error</code></td><td><code>A2EError</code></td></tr></tbody></table><p>Plugins extend this at startup by registering their own <code>TYPE_MAP</code> entries (e.g. <code>tool/call/req -&gt; ToolCallRequest</code>).</p>',14))])}const v=a(h,[["render",u]]);export{y as __pageData,v as default};
